"    {\n"
"        const float w = static_cast<float>(weights[ulong(row) * ulong(K)]);\n"
"        const device float* p0 = q3jl_pick<float>(loc[2 * lbase], s0, s1, s2, s3, s4, s5, s6, s7, s8, s9, s10, s11, s12, s13, s14, s15, s16, s17, s18, s19, s20, s21, s22, s23);\n"
"        const ulong o0 = ulong(loc[2 * lbase + 1]) * ulong(D) + ulong(col);\n"
"        for (uint i = 0; i < C; ++i) {\n"
"            if (col + i < uint(D)) {\n"
"                const float p = static_cast<float>(p0[o0 + i]) * w;     // Multiply(routed, w)\n"
"                t[i] = p + 0.0f;                                                // lid.y 0: op(v_0, Sum::init)\n"
"            }\n"
"        }\n"
"    }\n"
"    for (uint k = 1; k < uint(K); ++k) {\n"
"        const float w = static_cast<float>(weights[ulong(row) * ulong(K) + k]);\n"
"        const device float* pk = q3jl_pick<float>(loc[2 * (lbase + k)], s0, s1, s2, s3, s4, s5, s6, s7, s8, s9, s10, s11, s12, s13, s14, s15, s16, s17, s18, s19, s20, s21, s22, s23);\n"
"        const ulong ok = ulong(loc[2 * (lbase + k) + 1]) * ulong(D) + ulong(col);\n"
"        for (uint i = 0; i < C; ++i) {\n"
"            if (col + i < uint(D)) {\n"
"                const float p = static_cast<float>(pk[ok + i]) * w;\n"
"                t[i] = (p + 0.0f) + t[i];                                       // op(shared_vals[k], totals)\n"
"            }\n"
"        }\n"
"    }\n"
"    for (uint i = 0; i < C; ++i) {\n"
"        if (col + i < uint(D)) {\n"
"            out[obase + i] = t[i] + static_cast<float>(shared[obase + i]);     // Add(sum, shared)\n"
"        }\n"
"    }\n";

static const char text_73[] =
"#pragma METAL fp contract(off)\n"
"template <typename T>\n"
"inline const device T* q3jl_pick(int s, const device T* s0, const device T* s1, const device T* s2, const device T* s3, const device T* s4, const device T* s5, const device T* s6, const device T* s7, const device T* s8, const device T* s9, const device T* s10, const device T* s11, const device T* s12, const device T* s13, const device T* s14, const device T* s15, const device T* s16, const device T* s17, const device T* s18, const device T* s19, const device T* s20, const device T* s21, const device T* s22, const device T* s23) {\n"
"    switch (s) {\n"
"        case 0: return s0;\n"
"        case 1: return s1;\n"
"        case 2: return s2;\n"
"        case 3: return s3;\n"
"        case 4: return s4;\n"
"        case 5: return s5;\n"
"        case 6: return s6;\n"
"        case 7: return s7;\n"
"        case 8: return s8;\n"
"        case 9: return s9;\n"
"        case 10: return s10;\n"
"        case 11: return s11;\n"
"        case 12: return s12;\n"
"        case 13: return s13;\n"
"        case 14: return s14;\n"
"        case 15: return s15;\n"
"        case 16: return s16;\n"
"        case 17: return s17;\n"
"        case 18: return s18;\n"
"        case 19: return s19;\n"
"        case 20: return s20;\n"
"        case 21: return s21;\n"
"        case 22: return s22;\n"
"        default: return s23;\n"
"    }\n"
"}\n";

static const char text_74[] =
"#pragma METAL fp contract(off)\n"
"    // q3_prefill_dig_rot_take2_5120 retuned (mlx-serve native, 2026-09-30): its arithmetic element for element, one\n"
"    // simdgroup per (row, 128-block) writing BOTH outputs from one act load. Lane l holds block elements 4l .. 4l + 3.\n"
"    // The 128-point butterflies run in the lane text's bit order, element bit 0 first and bit 6 last (bits 0 and 1 in\n"
"    // registers, bits 2 .. 6 across lanes), each pair as (lower + upper, lower - upper): the same f32 values throughout.\n"
"    const float SCALE = as_type<float>(1035273459u);\n"
"    uint l = thread_index_in_simdgroup;\n"
"    uint blk = threadgroup_position_in_grid.x * 8u + simdgroup_index_in_threadgroup;\n"
"    uint r = threadgroup_position_in_grid.y;\n"
"    uint c0 = blk * 128u + 4u * l;\n"
"    int64_t src = (int64_t) ridx[r] * act_strides[0] + (int64_t) c0;\n"
"    int64_t slot = (int64_t) slots[rhs[r]];\n"
"    int64_t rg = slot * rin_g_strides[0] + (int64_t) c0 * rin_g_strides[1];\n"
"    int64_t ru = slot * rin_u_strides[0] + (int64_t) c0 * rin_u_strides[1];\n"
"    float wg[4];\n"
"    float wu[4];\n"
"    _Pragma(\"clang loop unroll(full)\")\n"
"    for (uint q = 0u; q < 4u; ++q) {\n"
"        float a = float(act[src + (int64_t) q]);\n"
"        wg[q] = a * float(rin_g[rg + (int64_t) q * rin_g_strides[1]]);\n"
"        wu[q] = a * float(rin_u[ru + (int64_t) q * rin_u_strides[1]]);\n"
"    }\n"
"    {\n"
"        float a0 = wg[0] + wg[1];\n"
"        float a1 = wg[0] - wg[1];\n"
"        float a2 = wg[2] + wg[3];\n"
"        float a3 = wg[2] - wg[3];\n"
"        wg[0] = a0 + a2;\n"
"        wg[2] = a0 - a2;\n"
"        wg[1] = a1 + a3;\n"
"        wg[3] = a1 - a3;\n"
"    }\n"
"    {\n"
"        float a0 = wu[0] + wu[1];\n"
"        float a1 = wu[0] - wu[1];\n"
"        float a2 = wu[2] + wu[3];\n"
"        float a3 = wu[2] - wu[3];\n"
"        wu[0] = a0 + a2;\n"
"        wu[2] = a0 - a2;\n"
"        wu[1] = a1 + a3;\n"
"        wu[3] = a1 - a3;\n"
"    }\n"
"    _Pragma(\"clang loop unroll(full)\")\n"
"    for (uint h = 1u; h < 32u; h <<= 1u) {\n"
"        bool upper = (l & h) != 0u;\n"
"        _Pragma(\"clang loop unroll(full)\")\n"
"        for (uint q = 0u; q < 4u; ++q) {\n"
"            float og = simd_shuffle_xor(wg[q], (ushort) h);\n"
"            float ou = simd_shuffle_xor(wu[q], (ushort) h);\n"
"            wg[q] = upper ? (og - wg[q]) : (wg[q] + og);\n"
"            wu[q] = upper ? (ou - wu[q]) : (wu[q] + ou);\n"
"        }\n"
"    }\n"
"    int64_t dst = (int64_t) r * 5120 + (int64_t) c0;\n"
"    _Pragma(\"clang loop unroll(full)\")\n"
"    for (uint q = 0u; q < 4u; ++q) {\n"
"        out_g[dst + (int64_t) q] = static_cast<half>(wg[q] * SCALE);\n"
"        out_u[dst + (int64_t) q] = static_cast<half>(wu[q] * SCALE);\n"
"    }\n";

static const char text_75[] =
"    // q3_prefill_dig_gemm_5120x2304_gu_xmul1hk3\n"
"    // at a 128-row M tile (mlx-serve native, 2026-09-30): 8 simdgroups (WM 4 x WN 2), each with the 64-row text's\n"
"    // 32 x 32 share (the same A fragments, decoded B values and tile_matmad_nax sequence per output), so one decoded\n"
"    // B stage feeds 128 rows. The decode jobs per lane follow NSG (JOBS = 8 / NSG); nothing else differs.\n"
"    constexpr int BM = 128;\n"
"    constexpr int BN = 64;\n"
"    constexpr int BK = 64;\n"
"    constexpr int WN = 2;\n"
"    constexpr int SM = 32;\n"
"    constexpr int SN = 32;\n"
"    constexpr int SK = 32;\n"
"    constexpr int TM = 2;\n"
"    constexpr int TN = 2;\n"
"    constexpr int TK = 2;\n"
"    constexpr int NSG = 8;\n"
"    constexpr int JOBS = 8 / NSG;\n"
"    constexpr int LDB = BK + 8;\n"
"    constexpr int KT = BK / 16;\n"
"    constexpr int NT = BN / 16;\n"
"    constexpr int KD = 5120;\n"
"    constexpr int WPT = 24;\n"
"    constexpr int SWPT = 24;\n"
"    constexpr int ND = 2304;\n"
"    constexpr int K16 = KD / 16;\n"
"    constexpr int N16 = ND / 16;\n"
"    constexpr int NTILES = ND / BN;\n"
"    constexpr int S = KD / BK;\n"
"    threadgroup uint4 dig_smem[BN * LDB * 2 / 16];\n"
"    threadgroup half* Bs = reinterpret_cast<threadgroup half*>(dig_smem);\n"
"\n"
"    const uint tid = thread_index_in_threadgroup;\n"
"    const uint sg = simdgroup_index_in_threadgroup;\n"
"    const uint lane = tid & 31u;\n"
"    const int g = int(threadgroup_position_in_grid.x);\n"
"    // this threadgroup's expert j: the last table entry whose first threadgroup is <= g (unused entries: INT_MAX)\n"
"    int j = 0;\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int q = 1; q < 16; ++q) {\n"
"        j = tbl[48 + q] <= g ? q : j;\n"
"    }\n"
"    const int slot = tbl[j];\n"
"    const int row0 = tbl[16 + j];\n"
"    const int rows = tbl[32 + j];\n"
"    const int local = g - tbl[48 + j];\n"
"    const int tiles_m = (rows + BM - 1) / BM;\n"
"    const int nt_all = local / tiles_m;\n"
"    const int m0 = (local - nt_all * tiles_m) * BM;\n"
"    const int op = nt_all / NTILES;\n"
"    const int n0 = (nt_all - op * NTILES) * BN;\n"
"    const int tm = SM * int(sg / WN);\n"
"    const short tn = short(SN * int(sg % WN));\n"
"    const int sgp_sm = min(SM, max(0, min(BM, rows - m0) - tm));\n"
"    (void)op;\n"
"    const device int16_t* code = op == 0 ? code0 : code1;\n"
"    // loader (the probe's map): job jj = trellis tile t (kt, nt) of the stage, column half h = sg & 1 (uniform per\n"
"    // simdgroup), column c7 = lane & 7 -> B^T row 16 nt + 8 h + c7, K slots 16 kt .. 16 kt + 15\n"
"    const uint h = sg & 1u;\n"
"    const uint c7 = lane & 7u;\n"
"    int dst_off[JOBS];\n"
"    int src_off[JOBS];\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int jj = 0; jj < JOBS; ++jj) {\n"
"        const int t = int(lane >> 3u) + 4 * (int(sg >> 1u) + (NSG / 2) * jj);\n"
"        const int kt = t / NT;\n"
"        const int nt = t % NT;\n"
"        dst_off[jj] = (nt * 16 + 8 * int(h) + int(c7)) * LDB + kt * 16;\n"
"        src_off[jj] = (kt * N16 + nt) * WPT;\n"
"    }\n"
"    const uint o0 = (3u * c7 + 23u) % 24u;\n"
"    const uint o1 = (3u * c7 + 24u) % 24u;\n"
"    const uint o2 = (3u * c7 + 25u) % 24u;\n"
"    const uint o3 = (3u * c7 + 26u) % 24u;\n"
"    const device uint* cd = reinterpret_cast<const device uint*>(code)\n"
"        + size_t(slot) * size_t(K16 * N16) * size_t(SWPT) + size_t(n0 / 16) * size_t(WPT);\n"
"    const device half* xa = (op == 0 ? x0 : x1) + (size_t(row0) + size_t(m0 + tm)) * size_t(KD);\n"
"    const bool full = sgp_sm == SM;\n"
"    NAXTile<float, TM, TN> Dtile;\n"
"    Dtile.clear();\n"
"    for (int s = 0; s < S; ++s) {\n"
"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int jj = 0; jj < JOBS; ++jj) {\n"
"            const device uint* tile = cd + size_t(s) * size_t(KT * N16 * WPT) + src_off[jj];\n"
"            if (h != 0u) {\n"
"                dig_dec_job<half, 1>(tile, o0, o1, o2, o3, Bs + dst_off[jj]);\n"
"            } else {\n"
"                dig_dec_job<half, 0>(tile, o0, o1, o2, o3, Bs + dst_off[jj]);\n"
"            }\n"
"        }\n"
"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
"        if (sgp_sm > 0) {\n"
"            STEEL_PRAGMA_NO_UNROLL\n"
"            for (int i = 0; i < 2; ++i) {\n"
"                NAXTile<half, TM, TK> Atile;\n"
"                NAXTile<half, TN, TK> Btile;\n"
"                volatile int compiler_barrier;\n"
"                if (full) {\n"
"                    Atile.load(xa + s * BK + i * SK, KD);\n"
"                } else {\n"
"                    Atile.load_safe(xa + s * BK + i * SK, KD, short2(SK, sgp_sm));\n"
"                }\n"
"                Btile.template load<half, LDB, 1>(Bs + tn * LDB + i * SK);\n"
"                tile_matmad_nax(Dtile, Atile, metal::bool_constant<false>{}, Btile, metal::bool_constant<true>{});\n"
"                (void)compiler_barrier;\n"
"            }\n"
"        }\n"
"    }\n"
"    if (sgp_sm > 0) {\n"
"        device float* zp = (op == 0 ? z0 : z1) + (size_t(row0) + size_t(m0 + tm)) * size_t(ND) + n0 + tn;\n"
"        if (full) {\n"
"            Dtile.store(zp, ND);\n"
"        } else {\n"
"            Dtile.store_safe(zp, ND, short2(SN, sgp_sm));\n"
"        }\n"
"    }\n";

static const char text_76[] =
"constexpr int PACKED_WORDS = 24, HALF_WORDS = 48;\n"
"// EXL3 SIMD-matrix prefill adapted from ddalcu/sushi 3f3ff7bc,\n"
"// src/exl3/expert_exl3_kernels.zig (GEMM_SIMDMAT_SOURCE).\n"
"// Keep this plugin's expert table, float32 outputs and gate/up interface.\n"
"constexpr int BM = 128, BN = 64, KD = 5120, ND = 2304;\n"
"constexpr int K16 = KD / 16, N16 = ND / 16, NTILES = ND / BN;\n"
"const int group = int(threadgroup_position_in_grid.x);\n"
"const uint sg = uint(simdgroup_index_in_threadgroup);\n"
"const ushort lane = ushort(thread_index_in_simdgroup);\n"
"int expert = 0;\n"
"STEEL_PRAGMA_UNROLL\n"
"for (int q = 1; q < 16; ++q) expert = tbl[48 + q] <= group ? q : expert;\n"
"const int slot = tbl[expert], row0 = tbl[16 + expert], rows = tbl[32 + expert];\n"
"const int local = group - tbl[48 + expert];\n"
"const int tiles_m = (rows + BM - 1) / BM;\n"
"const int nt_all = local / tiles_m;\n"
"const int m0 = (local - nt_all * tiles_m) * BM + int(sg / 2) * 32;\n"
"const int op = nt_all / NTILES;\n"
"const int n0 = (nt_all - op * NTILES) * BN + int(sg % 2) * 32;\n"
"const int live = min(32, rows - m0);\n"
"if (live <= 0) return;\n"
"const device half *left = op == 0 ? x0 : x1;\n"
"const device uint *codes = reinterpret_cast<const device uint *>(op == 0 ? code0 : code1)\n"
"    + size_t(slot) * K16 * N16 * PACKED_WORDS + size_t(n0 / 16) * PACKED_WORDS;\n"
"device float *dest = op == 0 ? z0 : z1;\n"
"const ushort qid = lane >> 2;\n"
"const ushort fm = (qid & 4) + ((lane >> 1) & 3);\n"
"const ushort fn = (qid & 2) * 2 + (lane & 1) * 2;\n"
"simdgroup_matrix<float, 8, 8> accum[4][4];\n"
"STEEL_PRAGMA_UNROLL\n"
"for (int m = 0; m < 4; ++m)\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int n = 0; n < 4; ++n)\n"
"        accum[m][n] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);\n"
"for (int tk = 0; tk < K16; ++tk) {\n"
"    simdgroup_matrix<half, 8, 8> a[4][2], b[2][4];\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int m = 0; m < 4; ++m) {\n"
"        const size_t at = size_t(row0 + m0 + min(m * 8 + int(fm), live - 1)) * KD + tk * 16 + fn;\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int k = 0; k < 2; ++k) {\n"
"            a[m][k].thread_elements()[0] = left[at + k * 8];\n"
"            a[m][k].thread_elements()[1] = left[at + k * 8 + 1];\n"
"        }\n"
"    }\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int tile = 0; tile < 2; ++tile) {\n"
"        half2 p0[4], p1[4];\n"
"        const device uint *words = codes + size_t(tk) * N16 * PACKED_WORDS + tile * PACKED_WORDS;\n"
"        smat_group<HALF_WORDS>(words, uint(fn) * 4 + (uint(fm) >> 1), p0);\n"
"        smat_group<HALF_WORDS>(words, (uint(fn) + 1) * 4 + (uint(fm) >> 1), p1);\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int j = 0; j < 4; ++j) {\n"
"            b[j & 1][2 * tile + (j >> 1)].thread_elements()[0] = p0[j][fm & 1];\n"
"            b[j & 1][2 * tile + (j >> 1)].thread_elements()[1] = p1[j][fm & 1];\n"
"        }\n"
"    }\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int k = 0; k < 2; ++k)\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int m = 0; m < 4; ++m)\n"
"            STEEL_PRAGMA_UNROLL\n"
"            for (int n = 0; n < 4; ++n)\n"
"                simdgroup_multiply_accumulate(accum[m][n], a[m][k], b[k][n], accum[m][n]);\n"
"}\n"
"STEEL_PRAGMA_UNROLL\n"
"for (int m = 0; m < 4; ++m) {\n"
"    const int row = m * 8 + int(fm);\n"
"    if (row < live) {\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int n = 0; n < 4; ++n) {\n"
"            const size_t out = size_t(row0 + m0 + row) * ND + n0 + n * 8 + fn;\n"
"            dest[out] = accum[m][n].thread_elements()[0];\n"
"            dest[out + 1] = accum[m][n].thread_elements()[1];\n"
"        }\n"
"    }\n"
"}\n";

static const char text_77[] =
"    // dsv41_prefill_dig_gemm_5120x2304_gu_xmul1hk3_m128\n"
"    // with the mul1h codebook through a threadgroup table (mlx-serve native, 2026-09-30): the B loader reads each\n"
"    // weight's half from a 1,024-entry table (the value dig_cb computes for its byte sum, filled once per\n"
"    // threadgroup) in place of the fma; the same halves, stores, A fragments and tile_matmad_nax sequence.\n"
"    constexpr int BM = 128;\n"
"    constexpr int BN = 64;\n"
"    constexpr int BK = 64;\n"
"    constexpr int WN = 2;\n"
"    constexpr int SM = 32;\n"
"    constexpr int SN = 32;\n"
"    constexpr int SK = 32;\n"
"    constexpr int TM = 2;\n"
"    constexpr int TN = 2;\n"
"    constexpr int TK = 2;\n"
"    constexpr int NSG = 8;\n"
"    constexpr int JOBS = 8 / NSG;\n"
"    constexpr int LDB = BK + 8;\n"
"    constexpr int KT = BK / 16;\n"
"    constexpr int NT = BN / 16;\n"
"    constexpr int KD = 5120;\n"
"    constexpr int WPT = 24;\n"
"    constexpr int SWPT = 24;\n"
"    constexpr int ND = 2304;\n"
"    constexpr int K16 = KD / 16;\n"
"    constexpr int N16 = ND / 16;\n"
"    constexpr int NTILES = ND / BN;\n"
"    constexpr int S = KD / BK;\n"
"    threadgroup uint4 dig_smem[BN * LDB * 2 / 16];\n"
"    threadgroup half* Bs = reinterpret_cast<threadgroup half*>(dig_smem);\n"
"    threadgroup half dig_lut[DIG_LUT];\n"
"\n"
"    const uint tid = thread_index_in_threadgroup;\n"
"    // the table: read after the first stage's barrier\n"
"    dig_lut_fill(dig_lut, tid, uint(NSG * 32));\n"
"    const uint sg = simdgroup_index_in_threadgroup;\n"
"    const uint lane = tid & 31u;\n"
"    const int g = int(threadgroup_position_in_grid.x);\n"
"    // this threadgroup's expert j: the last table entry whose first threadgroup is <= g (unused entries: INT_MAX)\n"
"    int j = 0;\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int q = 1; q < 16; ++q) {\n"
"        j = tbl[48 + q] <= g ? q : j;\n"
"    }\n"
"    const int slot = tbl[j];\n"
"    const int row0 = tbl[16 + j];\n"
"    const int rows = tbl[32 + j];\n"
"    const int local = g - tbl[48 + j];\n"
"    const int tiles_m = (rows + BM - 1) / BM;\n"
"    const int nt_all = local / tiles_m;\n"
"    const int m0 = (local - nt_all * tiles_m) * BM;\n"
"    const int op = nt_all / NTILES;\n"
"    const int n0 = (nt_all - op * NTILES) * BN;\n"
"    const int tm = SM * int(sg / WN);\n"
"    const short tn = short(SN * int(sg % WN));\n"
"    const int sgp_sm = min(SM, max(0, min(BM, rows - m0) - tm));\n"
"    (void)op;\n"
"    const device int16_t* code = op == 0 ? code0 : code1;\n"
"    // loader (the probe's map): job jj = trellis tile t (kt, nt) of the stage, column half h = sg & 1 (uniform per\n"
"    // simdgroup), column c7 = lane & 7 -> B^T row 16 nt + 8 h + c7, K slots 16 kt .. 16 kt + 15\n"
"    const uint h = sg & 1u;\n"
"    const uint c7 = lane & 7u;\n"
"    int dst_off[JOBS];\n"
"    int src_off[JOBS];\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int jj = 0; jj < JOBS; ++jj) {\n"
"        const int t = int(lane >> 3u) + 4 * (int(sg >> 1u) + (NSG / 2) * jj);\n"
"        const int kt = t / NT;\n"
"        const int nt = t % NT;\n"
"        dst_off[jj] = (nt * 16 + 8 * int(h) + int(c7)) * LDB + kt * 16;\n"
"        src_off[jj] = (kt * N16 + nt) * WPT;\n"
"    }\n"
"    const uint o0 = (3u * c7 + 23u) % 24u;\n"
"    const uint o1 = (3u * c7 + 24u) % 24u;\n"
"    const uint o2 = (3u * c7 + 25u) % 24u;\n"
"    const uint o3 = (3u * c7 + 26u) % 24u;\n"
"    const device uint* cd = reinterpret_cast<const device uint*>(code)\n"
"        + size_t(slot) * size_t(K16 * N16) * size_t(SWPT) + size_t(n0 / 16) * size_t(WPT);\n"
"    const device half* xa = (op == 0 ? x0 : x1) + (size_t(row0) + size_t(m0 + tm)) * size_t(KD);\n"
"    const bool full = sgp_sm == SM;\n"
"    NAXTile<float, TM, TN> Dtile;\n"
"    Dtile.clear();\n"
"    for (int s = 0; s < S; ++s) {\n"
"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int jj = 0; jj < JOBS; ++jj) {\n"
"            const device uint* tile = cd + size_t(s) * size_t(KT * N16 * WPT) + src_off[jj];\n"
"            if (h != 0u) {\n"
"                dig_dec_job_lut<half, 1>(tile, o0, o1, o2, o3, Bs + dst_off[jj], dig_lut);\n"
"            } else {\n"
"                dig_dec_job_lut<half, 0>(tile, o0, o1, o2, o3, Bs + dst_off[jj], dig_lut);\n"
"            }\n"
"        }\n"
"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
"        if (sgp_sm > 0) {\n"
"            STEEL_PRAGMA_NO_UNROLL\n"
"            for (int i = 0; i < 2; ++i) {\n"
"                NAXTile<half, TM, TK> Atile;\n"
"                NAXTile<half, TN, TK> Btile;\n"
"                volatile int compiler_barrier;\n"
"                if (full) {\n"
"                    Atile.load(xa + s * BK + i * SK, KD);\n"
"                } else {\n"
"                    Atile.load_safe(xa + s * BK + i * SK, KD, short2(SK, sgp_sm));\n"
"                }\n"
"                Btile.template load<half, LDB, 1>(Bs + tn * LDB + i * SK);\n"
"                tile_matmad_nax(Dtile, Atile, metal::bool_constant<false>{}, Btile, metal::bool_constant<true>{});\n"
"                (void)compiler_barrier;\n"
"            }\n"
"        }\n"
"    }\n"
"    if (sgp_sm > 0) {\n"
"        device float* zp = (op == 0 ? z0 : z1) + (size_t(row0) + size_t(m0 + tm)) * size_t(ND) + n0 + tn;\n"
"        if (full) {\n"
"            Dtile.store(zp, ND);\n"
"        } else {\n"
"            Dtile.store_safe(zp, ND, short2(SN, sgp_sm));\n"
"        }\n"
"    }\n";

