static const char text_89[] =
"\n"
"    constexpr uint C = 4;\n"
"    constexpr uint DC = uint(D) / C;\n"
"    const uint g = thread_position_in_grid.x;\n"
"    const uint row = g / DC;\n"
"    const uint col = (g - row * DC) * C;\n"
"    float c[16];\n"
"    for (uint i = 0; i < 16u; ++i) c[i] = hcp_tf32(comb[ulong(row) * 16u + i]);\n"
"    float r[4][C];\n"
"    for (uint j = 0; j < 4u; ++j)\n"
"        for (uint i = 0; i < C; ++i) r[j][i] = hcp_tf32(static_cast<float>(res[(ulong(row) * 4u + j) * ulong(D) + col + i]));\n"
"    for (uint k = 0; k < 4u; ++k) {\n"
"        const float pk = post[ulong(row) * 4u + k];\n"
"        for (uint i = 0; i < C; ++i) {\n"
"            const float p0 = hcp_ftz(c[k] * r[0][i]);                  // comb[j, k] x residual[j], j = 0..3\n"
"            const float p1 = hcp_ftz(c[4u + k] * r[1][i]);\n"
"            const float p2 = hcp_ftz(c[8u + k] * r[2][i]);\n"
"            const float p3 = hcp_ftz(c[12u + k] * r[3][i]);\n"
"            const float m = (p0 + p1) + (p2 + p3);                      // the einsum's word\n"
"            const float t = pk * static_cast<float>(x[ulong(row) * ulong(D) + col + i]);\n"
"            h[(ulong(row) * 4u + k) * ulong(D) + col + i] = t + m;      // the compiled tail: post x, then + mixed\n"
"        }\n"
"    }\n";

static const char text_90[] =
"#pragma METAL fp contract(off)\n"
"// The NAX f32 GEMM's numerics on the HC combine (MLX_ENABLE_TF32): operands truncated to TF32, products below the\n"
"// f32 normal range flushed to a signed zero, the K = 4 terms summed in pairs.\n"
"inline float hcp_tf32(float v) { return as_type<float>(as_type<uint>(v) & 0xFFFFE000u); }\n"
"inline float hcp_ftz(float v) { return metal::fabs(v) < 0x1p-126f ? metal::copysign(0.0f, v) : v; }\n";

static const char text_91[] =
"// dsv41_hcpost_tf32 on the bf16 stream (kv16-opt): x and res read through static_cast<float> as there, h stored as the f32\n"
"// word rounded to bf16 (static_cast<bfloat16_t>, the region's astype(.., x dtype)); its own text and MLX name.\n"
"\n"
"    constexpr uint C = 4;\n"
"    constexpr uint DC = uint(D) / C;\n"
"    const uint g = thread_position_in_grid.x;\n"
"    const uint row = g / DC;\n"
"    const uint col = (g - row * DC) * C;\n"
"    float c[16];\n"
"    for (uint i = 0; i < 16u; ++i) c[i] = hcp_tf32(comb[ulong(row) * 16u + i]);\n"
"    float r[4][C];\n"
"    for (uint j = 0; j < 4u; ++j)\n"
"        for (uint i = 0; i < C; ++i) r[j][i] = hcp_tf32(static_cast<float>(res[(ulong(row) * 4u + j) * ulong(D) + col + i]));\n"
"    for (uint k = 0; k < 4u; ++k) {\n"
"        const float pk = post[ulong(row) * 4u + k];\n"
"        for (uint i = 0; i < C; ++i) {\n"
"            const float p0 = hcp_ftz(c[k] * r[0][i]);                  // comb[j, k] x residual[j], j = 0..3\n"
"            const float p1 = hcp_ftz(c[4u + k] * r[1][i]);\n"
"            const float p2 = hcp_ftz(c[8u + k] * r[2][i]);\n"
"            const float p3 = hcp_ftz(c[12u + k] * r[3][i]);\n"
"            const float m = (p0 + p1) + (p2 + p3);                      // the einsum's word\n"
"            const float t = pk * static_cast<float>(x[ulong(row) * ulong(D) + col + i]);\n"
"            h[(ulong(row) * 4u + k) * ulong(D) + col + i] = static_cast<bfloat16_t>(t + m);   // post x, then + mixed; rounded to bf16\n"
"        }\n"
"    }\n";

