"      bool transpose_b = false>\n"
"  METAL_FUNC static constexpr void mma(\n"
"      thread dtype_frag_t<CType>& Cm0,\n"
"      thread dtype_frag_t<CType>& Cm1,\n"
"      const thread dtype_frag_t<AType>& Am0,\n"
"      const thread dtype_frag_t<AType>& Am1,\n"
"      metal::bool_constant<transpose_a>,\n"
"      const thread dtype_frag_t<BType>& B,\n"
"      metal::bool_constant<transpose_b>) {\n"
"    portable_mma16(Cm0, Am0, metal::bool_constant<transpose_a>{}, B, metal::bool_constant<transpose_b>{});\n"
"    portable_mma16(Cm1, Am1, metal::bool_constant<transpose_a>{}, B, metal::bool_constant<transpose_b>{});\n"
"  }\n"
"};\n"
"\n"
"template <\n"
"    typename T,\n"
"    short kTileRows_,\n"
"    short kTileCols_,\n"
"    class NAXFrag_ = BaseNAXFrag>\n"
"struct NAXTile {\n"
"  using NAXFrag_t = NAXFrag_;\n"
"  using elem_type = T;\n"
"\n"
"  STEEL_CONST short kFragRows = NAXFrag_t::kFragRows;\n"
"  STEEL_CONST short kFragCols = NAXFrag_t::kFragCols;\n"
"  STEEL_CONST short kElemsPerFrag = NAXFrag_t::kElemsPerFrag;\n"
"\n"
"  STEEL_CONST short kTileRows = kTileRows_;\n"
"  STEEL_CONST short kTileCols = kTileCols_;\n"
"\n"
"  STEEL_CONST short kRows = kTileRows * kFragRows;\n"
"  STEEL_CONST short kCols = kTileCols * kFragCols;\n"
"\n"
"  STEEL_CONST short kNumFrags = kTileRows * kTileCols;\n"
"  STEEL_CONST short kElemsPerTile = kNumFrags * kElemsPerFrag;\n"
"\n"
"  STEEL_CONST short kFragThrRows = NAXFrag_t::kElemRows;\n"
"  STEEL_CONST short kFragThrCols = NAXFrag_t::kElemCols;\n"
"  STEEL_CONST short kFragRowsJump = NAXFrag_t::kElemRowsJump;\n"
"\n"
"  STEEL_CONST short kRowsPerThread = kTileRows * NAXFrag_t::kElemRows;\n"
"  STEEL_CONST short kColsPerThread = kTileCols * NAXFrag_t::kElemCols;\n"
"\n"
"  typedef typename NAXFrag_t::template dtype_frag_t<T> frag_type;\n"
"\n"
"  frag_type val_frags[kNumFrags]; // = {frag_type(0)};\n"
"\n"
"  METAL_FUNC NAXTile() thread {}\n"
"\n"
"  METAL_FUNC constexpr void clear() thread {\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (short i = 0; i < kNumFrags; ++i) {\n"
"      val_frags[i] = frag_type(0);\n"
"    }\n"
"  }\n"
"\n"
"  METAL_FUNC constexpr thread frag_type& frag_at(const short i, const short j)\n"
"      thread {\n"
"    return val_frags[i * kTileCols + j];\n"
"  }\n"
"\n"
"  METAL_FUNC constexpr const thread frag_type& frag_at(\n"
"      const short i,\n"
"      const short j) const thread {\n"
"    return val_frags[i * kTileCols + j];\n"
"  }\n"
"\n"
"  template <int i, int j>\n"
"  METAL_FUNC constexpr thread frag_type& frag_at() thread {\n"
"    return val_frags[i * kTileCols + j];\n"
"  }\n"
"\n"
"  template <int i, int j>\n"
"  METAL_FUNC constexpr const thread frag_type& frag_at() const thread {\n"
"    return val_frags[i * kTileCols + j];\n"
"  }\n"
"\n"
"  template <bool transpose>\n"
"  METAL_FUNC constexpr thread frag_type& frag_at(\n"
"      const short i,\n"
"      const short j,\n"
"      metal::bool_constant<transpose>) thread {\n"
"    if constexpr (transpose) {\n"
"      return frag_at(j, i);\n"
"    } else {\n"
"      return frag_at(i, j);\n"
"    }\n"
"  }\n"
"\n"
"  template <bool transpose>\n"
"  METAL_FUNC constexpr const thread frag_type& frag_at(\n"
"      const short i,\n"
"      const short j,\n"
"      metal::bool_constant<transpose>) const thread {\n"
"    if constexpr (transpose) {\n"
"      return frag_at(j, i);\n"
"    } else {\n"
"      return frag_at(i, j);\n"
"    }\n"
"  }\n"
"\n"
"  template <int i, int j, bool transpose>\n"
"  METAL_FUNC constexpr thread frag_type& frag_at() thread {\n"
"    if constexpr (transpose) {\n"
"      return frag_at<j, i>();\n"
"    } else {\n"
"      return frag_at<i, j>();\n"
"    }\n"
"  }\n"
"\n"
"  template <int i, int j, bool transpose>\n"
"  METAL_FUNC constexpr const thread frag_type& frag_at() const thread {\n"
"    if constexpr (transpose) {\n"
"      return frag_at<j, i>();\n"
"    } else {\n"
"      return frag_at<i, j>();\n"
"    }\n"
"  }\n"
"\n"
"  METAL_FUNC thread elem_type* elems() thread {\n"
"    return reinterpret_cast<thread elem_type*>(val_frags);\n"
"  }\n"
"\n"
"  METAL_FUNC const thread elem_type* elems() const thread {\n"
"    return reinterpret_cast<const thread elem_type*>(val_frags);\n"
"  }\n"
"\n"
"  template <typename Op>\n"
"  METAL_FUNC void row_reduce(\n"
"      thread metal::vec<T, kRowsPerThread>& vals) const thread {\n"
"    auto vptr = (thread T*)(&vals);\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (short i = 0; i < kTileRows; ++i) {\n"
"      STEEL_PRAGMA_UNROLL\n"
"      for (short j = 0; j < kTileCols; ++j) {\n"
"        NAXFrag_t::template row_reduce<Op>(\n"
"            frag_at(i, j), &vptr[i * kFragThrRows]);\n"
"      }\n"
"    }\n"
"  }\n"
"\n"
"  template <typename Op>\n"
"  METAL_FUNC void row_bin_op(\n"
"      thread metal::vec<T, kRowsPerThread>& vals) thread {\n"
"    auto vptr = (thread T*)(&vals);\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (short i = 0; i < kTileRows; ++i) {\n"
"      STEEL_PRAGMA_UNROLL\n"
"      for (short j = 0; j < kTileCols; ++j) {\n"
"        NAXFrag_t::template row_bin_op<Op>(\n"
"            frag_at(i, j), &vptr[i * kFragThrRows]);\n"
"      }\n"
"    }\n"
"  }\n"
"\n"
"  template <typename U, int str_x, int str_y>\n"
"  METAL_FUNC void load(const threadgroup U* src) thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::load(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            src,\n"
"            Int<str_x>{},\n"
"            Int<str_y>{},\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"\n"
"  template <typename U, int str_x, int str_y>\n"
"  METAL_FUNC void store(threadgroup U* dst) const thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::store(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            dst,\n"
"            Int<str_x>{},\n"
"            Int<str_y>{},\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"\n"
"  template <typename U>\n"
"  METAL_FUNC void load(const device U* src, const int ld) thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::load(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            src,\n"
"            ld,\n"
"            Int<1>{},\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"\n"
"  template <typename U>\n"
"  METAL_FUNC void store(device U* dst, const int ld) const thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::store(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            dst,\n"
"            ld,\n"
"            Int<1>{},\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"\n"
"  template <typename U>\n"
"  METAL_FUNC void\n"
"  load_rows(const device U* src, const int ld, const short n_rows) thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::load_rows(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            src,\n"
"            ld,\n"
"            Int<1>{},\n"
"            n_rows,\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"\n"
"  template <typename U>\n"
"  METAL_FUNC void load_safe(\n"
"      const device U* src,\n"
"      const int ld,\n"
"      const short2 src_tile_dims) thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::load_safe(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            src,\n"
"            ld,\n"
"            Int<1>{},\n"
"            src_tile_dims.y,\n"
"            src_tile_dims.x,\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"\n"
"  template <typename U>\n"
"  METAL_FUNC void store_rows(device U* dst, const int ld, const short n_rows)\n"
"      const thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::store_rows(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            dst,\n"
"            ld,\n"
"            Int<1>{},\n"
"            n_rows,\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"\n"
"  template <typename U>\n"
"  METAL_FUNC void store_safe(\n"
"      device U* dst,\n"
"      const int ld,\n"
"      const short2 dst_tile_dims) const thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::store_safe(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            dst,\n"
"            ld,\n"
"            Int<1>{},\n"
"            dst_tile_dims.y,\n"
"            dst_tile_dims.x,\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"\n"
"  template <typename U>\n"
"  METAL_FUNC void store_slice(\n"
"      device U* dst,\n"
"      const int ld,\n"
"      const short2 start,\n"
"      const short2 stop) const thread {\n"
"    const_for_loop<0, kTileRows, 1>([&](auto idx_row) {\n"
"      const_for_loop<0, kTileCols, 1>([&](auto idx_col) {\n"
"        NAXFrag_t::store_slice(\n"
"            frag_at<idx_row.value, idx_col.value>(),\n"
"            dst,\n"
"            ld,\n"
"            Int<1>{},\n"
"            start.y,\n"
"            stop.y,\n"
"            start.x,\n"
"            stop.x,\n"
"            idx_row * Int<kFragRows>{},\n"
"            idx_col * Int<kFragCols>{});\n"
"      });\n"
"    });\n"
"  }\n"
"};\n"
"\n"
"template <\n"
"    class CTile,\n"
"    class ATile,\n"
"    class BTile,\n"
"    bool transpose_a,\n"
"    bool transpose_b>\n"
"METAL_FUNC void tile_matmad_nax(\n"
"    thread CTile& C,\n"
"    thread ATile& A,\n"
"    metal::bool_constant<transpose_a>,\n"
"    thread BTile& B,\n"
"    metal::bool_constant<transpose_b>) {\n"
"  // Static checks\n"
"  constexpr short TMa = transpose_a ? ATile::kTileCols : ATile::kTileRows;\n"
"  constexpr short TM = CTile::kTileRows;\n"
"  static_assert(TMa == TM, \"MXU tile matmul: M dimensions do not match\");\n"
"\n"
"  constexpr short TNb = transpose_b ? BTile::kTileRows : BTile::kTileCols;\n"
"  constexpr short TN = CTile::kTileCols;\n"
"  static_assert(TNb == TN, \"MXU tile matmul: N dimensions do not match\");\n"
"\n"
"  constexpr short TKa = transpose_a ? ATile::kTileRows : ATile::kTileCols;\n"
"  constexpr short TK = transpose_b ? BTile::kTileCols : BTile::kTileRows;\n"
"  static_assert(TKa == TK, \"MXU tile matmul: K dimensions do not match\");\n"
"\n"
"  constexpr auto ta = metal::bool_constant<transpose_a>{};\n"
"  constexpr auto tb = metal::bool_constant<transpose_b>{};\n"
"\n"
"  if constexpr (TN == 1 && TM % 2 == 0) {\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (short mm = 0; mm < TM; mm += 2) {\n"
"      STEEL_PRAGMA_UNROLL\n"
"      for (short nn = 0; nn < TN; ++nn) {\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (short kk = 0; kk < TK; ++kk) {\n"
"          CTile::NAXFrag_t::mma(\n"
"              C.frag_at(mm, nn),\n"
"              C.frag_at(mm + 1, nn),\n"
"              A.frag_at(mm, kk, ta),\n"
"              A.frag_at(mm + 1, kk, ta),\n"
"              metal::bool_constant<transpose_a>{},\n"
"              B.frag_at(kk, nn, tb),\n"
"              metal::bool_constant<transpose_b>{});\n"
"        }\n"
"      }\n"
"    }\n"
"  } else if constexpr (TN % 2 == 0) {\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (short mm = 0; mm < TM; ++mm) {\n"
"      STEEL_PRAGMA_UNROLL\n"
"      for (short nn = 0; nn < TN; nn += 2) {\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (short kk = 0; kk < TK; ++kk) {\n"
"          CTile::NAXFrag_t::mma(\n"
"              C.frag_at(mm, nn),\n"
"              C.frag_at(mm, nn + 1),\n"
"              A.frag_at(mm, kk, ta),\n"
"              metal::bool_constant<transpose_a>{},\n"
"              B.frag_at(kk, nn, tb),\n"
"              B.frag_at(kk, nn + 1, tb),\n"
"              metal::bool_constant<transpose_b>{});\n"
"        }\n"
"      }\n"
"    }\n"
"  }\n"
"}\n"
"\n"
"} // namespace steel\n"
"} // namespace mlx\n"
"\n"
"// ---- EXL3 DIG helpers (q3_exl3_dig_kernels.py, 2026-09-27): codebook mul1h, K = 2 (16 u32 words per tile)\n"
"using namespace mlx::steel;\n"
"\n"
"METAL_FUNC half dig_cb(uint w) {\n"
"  const uint x = w * 2212286765u;\n"
"  const uint t = (x & 0x00ff00ffu) + ((x >> 8u) & 0x00ff00ffu);\n"
"  const half hs = as_type<half>(ushort((t * 0x00010001u + 0x64000000u) >> 16u));\n"
"  return metal::fma(hs, as_type<half>(ushort(0x1EEEu)), as_type<half>(ushort(0xC931u)));\n"
"}\n"
"\n"
"// two decoded weights as T (f16: the value itself; bf16: round to nearest even of the exact f16 value), packed\n"
"template <typename T>\n"
"METAL_FUNC uint dig_pk(half a, half b) {\n"
"  return uint(as_type<ushort>(static_cast<T>(float(a)))) | (uint(as_type<ushort>(static_cast<T>(float(b)))) << 16u);\n"
"}\n"
"\n"
"// the 16 windows of one tile column in half h (constant plan per half), P = the column's 3 u32 words\n"
"template <int H>\n"
"METAL_FUNC void dig_windows(thread const uint* P, thread half* v);\n"
"\n"
"template <>\n"
"METAL_FUNC void dig_windows<0>(thread const uint* P, thread half* v) {\n"
"  { const uint x = (P[1] >> 28u) | ((P[0] << 1u) << 3u);\n"
"    v[1] = dig_cb(x & 0xffffu); v[0] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[1] >> 12u) | ((P[0] << 1u) << 19u);\n"
"    v[3] = dig_cb(x & 0xffffu); v[2] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[2] >> 28u) | ((P[1] << 1u) << 3u);\n"
"    v[5] = dig_cb(x & 0xffffu); v[4] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[2] >> 12u) | ((P[1] << 1u) << 19u);\n"
"    v[7] = dig_cb(x & 0xffffu); v[6] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[1] >> 24u) | ((P[0] << 1u) << 7u);\n"
"    v[9] = dig_cb(x & 0xffffu); v[8] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[1] >> 8u) | ((P[0] << 1u) << 23u);\n"
"    v[11] = dig_cb(x & 0xffffu); v[10] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[2] >> 24u) | ((P[1] << 1u) << 7u);\n"
"    v[13] = dig_cb(x & 0xffffu); v[12] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[2] >> 8u) | ((P[1] << 1u) << 23u);\n"
"    v[15] = dig_cb(x & 0xffffu); v[14] = dig_cb((x >> 2u) & 0xffffu); }\n"
"}\n"
"\n"
"template <>\n"
"METAL_FUNC void dig_windows<1>(thread const uint* P, thread half* v) {\n"
"  { const uint x = (P[1] >> 20u) | ((P[0] << 1u) << 11u);\n"
"    v[1] = dig_cb(x & 0xffffu); v[0] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[1] >> 4u) | ((P[0] << 1u) << 27u);\n"
"    v[3] = dig_cb(x & 0xffffu); v[2] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[2] >> 20u) | ((P[1] << 1u) << 11u);\n"
"    v[5] = dig_cb(x & 0xffffu); v[4] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[2] >> 4u) | ((P[1] << 1u) << 27u);\n"
"    v[7] = dig_cb(x & 0xffffu); v[6] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[1] >> 16u) | ((P[0] << 1u) << 15u);\n"
"    v[9] = dig_cb(x & 0xffffu); v[8] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[1] >> 0u) | ((P[0] << 1u) << 31u);\n"
"    v[11] = dig_cb(x & 0xffffu); v[10] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[2] >> 16u) | ((P[1] << 1u) << 15u);\n"
"    v[13] = dig_cb(x & 0xffffu); v[12] = dig_cb((x >> 2u) & 0xffffu); }\n"
"  { const uint x = (P[2] >> 0u) | ((P[1] << 1u) << 31u);\n"
"    v[15] = dig_cb(x & 0xffffu); v[14] = dig_cb((x >> 2u) & 0xffffu); }\n"
"}\n"
"\n"
"// one 16-weight job: column c = 8 H + c7 of a 16 x 16 trellis tile (16 u32 words at `tile`; o_t = the words\n"
"// (2 c7 + 15 + t) mod 16) -> the 16 consecutive K slots of B^T row n at `dst` (two 16-byte stores)\n"
"template <typename T, int H>\n"
"METAL_FUNC void dig_dec_job(const device uint* tile, uint o0, uint o1, uint o2, threadgroup T* dst) {\n"
"  uint P[3];\n"
"  P[0] = tile[o0];\n"
"  P[1] = tile[o1];\n"
"  P[2] = tile[o2];\n"
"  half v[16];\n"
"  dig_windows<H>(P, v);\n"
"  threadgroup uint4* d4 = reinterpret_cast<threadgroup uint4*>(dst);\n"
"  d4[0] = uint4(dig_pk<T>(v[0], v[1]), dig_pk<T>(v[2], v[3]), dig_pk<T>(v[4], v[5]), dig_pk<T>(v[6], v[7]));\n"
"  d4[1] = uint4(dig_pk<T>(v[8], v[9]), dig_pk<T>(v[10], v[11]), dig_pk<T>(v[12], v[13]), dig_pk<T>(v[14], v[15]));\n"
"}\n"
"\n"
"// Sushi SIMD reader. N is the number of uint16 words in each 16x16 tile:\n"
"// K2: N=32, K3: N=48. dig_cb remains the unmodified upstream mul1h codebook.\n"
"static inline half2 exl3_pairh(uint2 cw) { return half2(dig_cb(cw.x), dig_cb(cw.y)); }\n"
"static inline constexpr uint exl3_end(uint N, uint j) { return ((j + 1u) * N) >> 4u; }\n"
"static inline ulong exl3_window(const device uint *words, uint end, uint nwords, bool full) {\n"
"  const uint last = (end - 1u) >> 5u;\n"
"  const uint prev = last == 0u ? nwords - 1u : last - 1u;\n"
"  const uint s = (0u - end) & 31u;\n"
"  ulong bits = (((ulong)words[prev] << 32u) | (ulong)words[last]) >> s;\n"
"  if (full) bits |= ((ulong)words[prev == 0u ? nwords - 1u : prev - 1u] << 32u) << (32u - s);\n"
"  return bits;\n"
"}\n"
"#define SMAT_UNROLL _Pragma(\"clang loop unroll(full)\")\n"
"static inline half2 smat_pair(uint f, uint s0, uint s1) {\n"
"  return exl3_pairh(uint2((f >> s0) & 0xffffu, (f >> s1) & 0xffffu));\n"
"}\n"
"// The group's weights 0..L come from one 32-bit funnel ending at weight L, the rest from\n"
"// one ending at weight 7: L is the widest split whose first codeword still fits.\n"
"static inline constexpr uint smat_split(uint N) {\n"
"  return exl3_end(N, 7u) - exl3_end(N, 0u) <= 16u ? 7u : exl3_end(N, 5u) - exl3_end(N, 0u) <= 16u ? 5u : 3u;\n"
"}\n"
"template<uint N>\n"
"static inline void smat_group(const device uint *words, uint g, thread half2 *p) {\n"
"  if (N == 64u) {\n"
"    const ulong m = ((ulong)words[(g + 31u) & 31u] << 32u) | (ulong)words[g];\n"
"    SMAT_UNROLL for (uint j = 0u; j < 4u; j++) p[j] = smat_pair(uint(m >> (24u - 8u * j)), 4u, 0u);\n"
"  } else if (exl3_end(N, 3u) - exl3_end(N, 0u) > 16u || N / 2u - exl3_end(N, 4u) > 16u) {\n"
"    constexpr uint W = N / 2u;\n"
"    const ulong lo = exl3_window(words, W * g + exl3_end(N, 3u), W, true);\n"
"    const ulong hi = exl3_window(words, W * g + W, W, true);\n"
"    SMAT_UNROLL for (uint j = 0u; j < 4u; j++) {\n"
"      const ulong bits = j < 2u ? lo : hi;\n"
"      const uint end = j < 2u ? exl3_end(N, 3u) : W;\n"
"      p[j] = exl3_pairh(uint2(uint(bits >> (end - exl3_end(N, 2u * j))) & 0xffffu, uint(bits >> (end - exl3_end(N, 2u * j + 1u))) & 0xffffu));\n"
"    }\n"
"  } else {\n"
"    constexpr uint W = N / 2u;\n"
"    constexpr uint L = smat_split(N);\n"
"    const uint lo = uint(exl3_window(words, W * g + exl3_end(N, L), W, false));\n"
"    const uint hi = uint(exl3_window(words, W * g + W, W, false));\n"
"    constexpr uint E = exl3_end(N, L);\n"
"    p[0] = smat_pair(lo, E - exl3_end(N, 0u), E - exl3_end(N, 1u));\n"
"    p[1] = smat_pair(lo, E - exl3_end(N, 2u), E - exl3_end(N, 3u));\n"
"    p[2] = L >= 5u ? smat_pair(lo, E - exl3_end(N, 4u), E - exl3_end(N, 5u)) : smat_pair(hi, W - exl3_end(N, 4u), W - exl3_end(N, 5u));\n"
"    p[3] = L == 7u ? smat_pair(lo, E - exl3_end(N, 6u), 0u) : smat_pair(hi, W - exl3_end(N, 6u), 0u);\n"
"  }\n"
"}\n";

static const char text_124[] =
"constexpr int PACKED_WORDS = 16, HALF_WORDS = 32;\n"
"// EXL3 SIMD-matrix prefill adapted from ddalcu/sushi 3f3ff7bc,\n"
"// src/exl3/expert_exl3_kernels.zig (GEMM_SIMDMAT_SOURCE).\n"
"// Keep this plugin's expert table, float32 outputs and gate/up interface.\n"
"constexpr int BM = 128, BN = 64, KD = 5120, ND = 2304;\n"
"constexpr int K16 = KD / 16, N16 = ND / 16, NTILES = ND / BN;\n"
"const int group = int(threadgroup_position_in_grid.x);\n"
"const uint sg = uint(simdgroup_index_in_threadgroup);\n"
"const ushort lane = ushort(thread_index_in_simdgroup);\n"
"int expert = 0;\n"
"STEEL_PRAGMA_UNROLL\n"
"for (int q = 1; q < 16; ++q) expert = tbl[48 + q] <= group ? q : expert;\n"
"const int slot = tbl[expert], row0 = tbl[16 + expert], rows = tbl[32 + expert];\n"
"const int local = group - tbl[48 + expert];\n"
"const int tiles_m = (rows + BM - 1) / BM;\n"
"const int nt_all = local / tiles_m;\n"
"const int m0 = (local - nt_all * tiles_m) * BM + int(sg / 2) * 32;\n"
"const int op = nt_all / NTILES;\n"
"const int n0 = (nt_all - op * NTILES) * BN + int(sg % 2) * 32;\n"
"const int live = min(32, rows - m0);\n"
"if (live <= 0) return;\n"
"const device half *left = op == 0 ? x0 : x1;\n"
"const device uint *codes = reinterpret_cast<const device uint *>(op == 0 ? code0 : code1)\n"
"    + size_t(slot) * K16 * N16 * PACKED_WORDS + size_t(n0 / 16) * PACKED_WORDS;\n"
"device float *dest = op == 0 ? z0 : z1;\n"
"const ushort qid = lane >> 2;\n"
"const ushort fm = (qid & 4) + ((lane >> 1) & 3);\n"
"const ushort fn = (qid & 2) * 2 + (lane & 1) * 2;\n"
"simdgroup_matrix<float, 8, 8> accum[4][4];\n"
"STEEL_PRAGMA_UNROLL\n"
"for (int m = 0; m < 4; ++m)\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int n = 0; n < 4; ++n)\n"
"        accum[m][n] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);\n"
"for (int tk = 0; tk < K16; ++tk) {\n"
"    simdgroup_matrix<half, 8, 8> a[4][2], b[2][4];\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int m = 0; m < 4; ++m) {\n"
"        const size_t at = size_t(row0 + m0 + min(m * 8 + int(fm), live - 1)) * KD + tk * 16 + fn;\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int k = 0; k < 2; ++k) {\n"
"            a[m][k].thread_elements()[0] = left[at + k * 8];\n"
"            a[m][k].thread_elements()[1] = left[at + k * 8 + 1];\n"
"        }\n"
"    }\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int tile = 0; tile < 2; ++tile) {\n"
"        half2 p0[4], p1[4];\n"
"        const device uint *words = codes + size_t(tk) * N16 * PACKED_WORDS + tile * PACKED_WORDS;\n"
"        smat_group<HALF_WORDS>(words, uint(fn) * 4 + (uint(fm) >> 1), p0);\n"
"        smat_group<HALF_WORDS>(words, (uint(fn) + 1) * 4 + (uint(fm) >> 1), p1);\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int j = 0; j < 4; ++j) {\n"
"            b[j & 1][2 * tile + (j >> 1)].thread_elements()[0] = p0[j][fm & 1];\n"
"            b[j & 1][2 * tile + (j >> 1)].thread_elements()[1] = p1[j][fm & 1];\n"
"        }\n"
"    }\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int k = 0; k < 2; ++k)\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int m = 0; m < 4; ++m)\n"
"            STEEL_PRAGMA_UNROLL\n"
"            for (int n = 0; n < 4; ++n)\n"
"                simdgroup_multiply_accumulate(accum[m][n], a[m][k], b[k][n], accum[m][n]);\n"
"}\n"
"STEEL_PRAGMA_UNROLL\n"
"for (int m = 0; m < 4; ++m) {\n"
"    const int row = m * 8 + int(fm);\n"
"    if (row < live) {\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int n = 0; n < 4; ++n) {\n"
"            const size_t out = size_t(row0 + m0 + row) * ND + n0 + n * 8 + fn;\n"
"            dest[out] = accum[m][n].thread_elements()[0];\n"
"            dest[out + 1] = accum[m][n].thread_elements()[1];\n"
"        }\n"
"    }\n"
"}\n";

static const char text_125[] =
"    // q3_prefill_dig_gemm_2304x5120_xmul1hk2\n"
"    // at a 128-row M tile (mlx-serve native, 2026-09-30): 8 simdgroups (WM 4 x WN 2), each with the 64-row text's\n"
"    // 32 x 32 share (the same A fragments, decoded B values and tile_matmad_nax sequence per output), so one decoded\n"
"    // B stage feeds 128 rows. The decode jobs per lane follow NSG (JOBS = 8 / NSG); nothing else differs.\n"
"    constexpr int BM = 128;\n"
"    constexpr int BN = 64;\n"
"    constexpr int BK = 64;\n"
"    constexpr int WN = 2;\n"
"    constexpr int SM = 32;\n"
"    constexpr int SN = 32;\n"
"    constexpr int SK = 32;\n"
"    constexpr int TM = 2;\n"
"    constexpr int TN = 2;\n"
"    constexpr int TK = 2;\n"
"    constexpr int NSG = 8;\n"
"    constexpr int JOBS = 8 / NSG;\n"
"    constexpr int LDB = BK + 8;\n"
"    constexpr int KT = BK / 16;\n"
"    constexpr int NT = BN / 16;\n"
"    constexpr int KD = 2304;\n"
"    constexpr int WPT = 16;\n"
"    constexpr int SWPT = 16;\n"
"    constexpr int ND = 5120;\n"
"    constexpr int K16 = KD / 16;\n"
"    constexpr int N16 = ND / 16;\n"
"    constexpr int NTILES = ND / BN;\n"
"    constexpr int S = KD / BK;\n"
"    threadgroup uint4 dig_smem[BN * LDB * 2 / 16];\n"
"    threadgroup half* Bs = reinterpret_cast<threadgroup half*>(dig_smem);\n"
"\n"
"    const uint tid = thread_index_in_threadgroup;\n"
"    const uint sg = simdgroup_index_in_threadgroup;\n"
"    const uint lane = tid & 31u;\n"
"    const int g = int(threadgroup_position_in_grid.x);\n"
"    // this threadgroup's expert j: the last table entry whose first threadgroup is <= g (unused entries: INT_MAX)\n"
"    int j = 0;\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int q = 1; q < 16; ++q) {\n"
"        j = tbl[48 + q] <= g ? q : j;\n"
"    }\n"
"    const int slot = tbl[j];\n"
"    const int row0 = tbl[16 + j];\n"
"    const int rows = tbl[32 + j];\n"
"    const int local = g - tbl[48 + j];\n"
"    const int tiles_m = (rows + BM - 1) / BM;\n"
"    const int nt_all = local / tiles_m;\n"
"    const int m0 = (local - nt_all * tiles_m) * BM;\n"
"    const int op = nt_all / NTILES;\n"
"    const int n0 = (nt_all - op * NTILES) * BN;\n"
"    const int tm = SM * int(sg / WN);\n"
"    const short tn = short(SN * int(sg % WN));\n"
"    const int sgp_sm = min(SM, max(0, min(BM, rows - m0) - tm));\n"
"    (void)op;\n"
"    const device int16_t* code = code0;\n"
"    // loader (the probe's map): job jj = trellis tile t (kt, nt) of the stage, column half h = sg & 1 (uniform per\n"
"    // simdgroup), column c7 = lane & 7 -> B^T row 16 nt + 8 h + c7, K slots 16 kt .. 16 kt + 15\n"
"    const uint h = sg & 1u;\n"
"    const uint c7 = lane & 7u;\n"
"    int dst_off[JOBS];\n"
"    int src_off[JOBS];\n"
"    STEEL_PRAGMA_UNROLL\n"
"    for (int jj = 0; jj < JOBS; ++jj) {\n"
"        const int t = int(lane >> 3u) + 4 * (int(sg >> 1u) + (NSG / 2) * jj);\n"
"        const int kt = t / NT;\n"
"        const int nt = t % NT;\n"
"        dst_off[jj] = (nt * 16 + 8 * int(h) + int(c7)) * LDB + kt * 16;\n"
"        src_off[jj] = (kt * N16 + nt) * WPT;\n"
"    }\n"
"    const uint o0 = (2u * c7 + 15u) % 16u;\n"
"    const uint o1 = (2u * c7 + 16u) % 16u;\n"
"    const uint o2 = (2u * c7 + 17u) % 16u;\n"
"    const device uint* cd = reinterpret_cast<const device uint*>(code)\n"
"        + size_t(slot) * size_t(K16 * N16) * size_t(SWPT) + size_t(n0 / 16) * size_t(WPT);\n"
"    const device half* xa = x + (size_t(row0) + size_t(m0 + tm)) * size_t(KD);\n"
"    const bool full = sgp_sm == SM;\n"
"    NAXTile<float, TM, TN> Dtile;\n"
"    Dtile.clear();\n"
"    for (int s = 0; s < S; ++s) {\n"
"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
"        STEEL_PRAGMA_UNROLL\n"
"        for (int jj = 0; jj < JOBS; ++jj) {\n"
"            const device uint* tile = cd + size_t(s) * size_t(KT * N16 * WPT) + src_off[jj];\n"
"            if (h != 0u) {\n"
"                dig_dec_job<half, 1>(tile, o0, o1, o2, Bs + dst_off[jj]);\n"
"            } else {\n"
"                dig_dec_job<half, 0>(tile, o0, o1, o2, Bs + dst_off[jj]);\n"
"            }\n"
"        }\n"
"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
"        if (sgp_sm > 0) {\n"
"            STEEL_PRAGMA_NO_UNROLL\n"
"            for (int i = 0; i < 2; ++i) {\n"
"                NAXTile<half, TM, TK> Atile;\n"
"                NAXTile<half, TN, TK> Btile;\n"
"                volatile int compiler_barrier;\n"
"                if (full) {\n"
"                    Atile.load(xa + s * BK + i * SK, KD);\n"
"                } else {\n"
"                    Atile.load_safe(xa + s * BK + i * SK, KD, short2(SK, sgp_sm));\n"
"                }\n"
"                Btile.template load<half, LDB, 1>(Bs + tn * LDB + i * SK);\n"
"                tile_matmad_nax(Dtile, Atile, metal::bool_constant<false>{}, Btile, metal::bool_constant<true>{});\n"
"                (void)compiler_barrier;\n"
"            }\n"
"        }\n"
"    }\n"
"    if (sgp_sm > 0) {\n"
"        device float* zp = z0 + (size_t(row0) + size_t(m0 + tm)) * size_t(ND) + n0 + tn;\n"
"        if (full) {\n"
"            Dtile.store(zp, ND);\n"
"        } else {\n"
"            Dtile.store_safe(zp, ND, short2(SN, sgp_sm));\n"
"        }\n"
"    }\n";

