static bool flag(const char *name) { const char *v = getenv(name); return v && !strcmp(v, "1"); }
__attribute__((constructor)) static void check_machine(void) {
    char brand[128] = {0}; size_t n=sizeof brand;
    if (sysctlbyname("machdep.cpu.brand_string",brand,&n,NULL,0) || !strstr(brand,"Apple M2")) abort();
    fprintf(stderr,"[m2-decode-experiment] C02=%d C03=%d; defaults are off\n",flag("DSV41_EXPERIMENT_GU_PAIR"),flag("DSV41_EXPERIMENT_DECODE_TILE2"));
}
static handle patched_new(const char *name,handle ins,handle outs,const char *source,const char *header,bool contiguous,bool atomic) {
    bool known=false;
    for(size_t i=0;i<sizeof patches/sizeof patches[0];++i) {
        const struct patch *p=&patches[i]; if(strcmp(name,p->name)) continue; known=true;
        if(strcmp(source,p->source)||strcmp(header,p->header)||contiguous!=p->contiguous||atomic!=p->atomic) continue;
        const unsigned variant=(flag("DSV41_EXPERIMENT_GU_PAIR")?1u:0u)|(flag("DSV41_EXPERIMENT_DECODE_TILE2")?2u:0u);
        if(strcmp(p->body[variant],p->body[0])) fprintf(stderr,"[m2-decode-experiment] %s variant=%u\n",name,variant);
        return mlx_fast_metal_kernel_new(name,ins,outs,p->body[variant],p->patched_header,contiguous,atomic);
    }
    if(known||strstr(header,"struct BaseNAXFrag")) {fprintf(stderr,"[m2-decode-experiment] source mismatch: %s\n",name);return(handle){NULL};}
    return mlx_fast_metal_kernel_new(name,ins,outs,source,header,contiguous,atomic);
}
__attribute__((used,section("__DATA,__interpose")))
static const struct{const void *replacement,*original;} interpose[]={{(const void*)patched_new,(const void*)mlx_fast_metal_kernel_new}};
